INSERT INTO products (category_id, brand_id, product_code, name, slug, description, warranty_months) SELECT c.id, b.id, 'ML-010', 'Máy lạnh Kazen Inverter 2HP', 'may-lanh-ml-010', 'Máy lạnh Kazen – dữ liệu mô phỏng cho demo, không phải sản phẩm thật.', 24 FROM categories c JOIN brands b ON b.name = 'Kazen' WHERE c.slug = 'may-lanh' ON DUPLICATE KEY UPDATE name = VALUES(name), description = VALUES(description);
INSERT INTO product_attribute_values (product_id, attribute_id, value_number) SELECT p.id, a.id, 18000 FROM products p JOIN product_attributes a ON a.category_id = p.category_id AND a.attribute_key = 'cooling_btu' WHERE p.product_code = 'ML-010' ON DUPLICATE KEY UPDATE value_number = VALUES(value_number);
