INSERT INTO product_attribute_values (product_id, attribute_id, value_number) SELECT p.id, a.id, 870 FROM products p JOIN product_attributes a ON a.category_id = p.category_id AND a.attribute_key = 'indoor_width_mm' WHERE p.product_code = 'ML-010' ON DUPLICATE KEY UPDATE value_number = VALUES(value_number);
INSERT INTO product_attribute_values (product_id, attribute_id, value_boolean) SELECT p.id, a.id, 1 FROM products p JOIN product_attributes a ON a.category_id = p.category_id AND a.attribute_key = 'inverter' WHERE p.product_code = 'ML-010' ON DUPLICATE KEY UPDATE value_boolean = VALUES(value_boolean);
